// Integration: schema/round-v1.schema.json accepts the engine-played rounds (tests/fixtures/rounds/v4c, regenerated by
// the real sim engine), including strokes whose draw carries an imported flight shape (apex_m, land_deg); the JSON
// schema and contract/round.js validateRound agree on the draw block.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateRound } from '../../app/src/contract/round.js';
import { replayRound } from '../../app/src/sim/round.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const schema = JSON.parse(readFileSync(join(ROOT, 'schema/round-v1.schema.json'), 'utf8'));

// ---- the small JSON Schema 2020-12 checker of contract.schema.test.mjs, for the round schema ----
const ANNOTATIONS = new Set(['$schema', '$id', 'title', 'description', '$defs', '$comment', 'examples', 'default']);
const typeOf = (v) => (v === null ? 'null' : Array.isArray(v) ? 'array' : typeof v);
const isType = (t, v) => (t === 'integer' ? Number.isInteger(v) : t === 'number' ? typeof v === 'number' && Number.isFinite(v) : typeOf(v) === t);
const valid = (s, v) => { const e = []; check(s, v, '', e); return e.length === 0; };
const KEYWORDS = {
  $ref: () => {},
  format: () => {}, // annotation only (date-time strings are checked by validateRound)
  type: (t, s, v, p, e) => { if (!(Array.isArray(t) ? t : [t]).some((x) => isType(x, v))) e.push(`${p}: type ${JSON.stringify(t)}`); },
  const: (c, s, v, p, e) => { if (JSON.stringify(c) !== JSON.stringify(v)) e.push(`${p}: const`); },
  enum: (en, s, v, p, e) => { if (!en.some((x) => JSON.stringify(x) === JSON.stringify(v))) e.push(`${p}: enum`); },
  pattern: (re, s, v, p, e) => { if (typeof v === 'string' && !new RegExp(re).test(v)) e.push(`${p}: pattern`); },
  minLength: (n, s, v, p, e) => { if (typeof v === 'string' && v.length < n) e.push(`${p}: minLength`); },
  maxLength: (n, s, v, p, e) => { if (typeof v === 'string' && v.length > n) e.push(`${p}: maxLength`); },
  minimum: (n, s, v, p, e) => { if (typeof v === 'number' && v < n) e.push(`${p}: minimum`); },
  maximum: (n, s, v, p, e) => { if (typeof v === 'number' && v > n) e.push(`${p}: maximum`); },
  exclusiveMinimum: (n, s, v, p, e) => { if (typeof v === 'number' && v <= n) e.push(`${p}: exclusiveMinimum`); },
  exclusiveMaximum: (n, s, v, p, e) => { if (typeof v === 'number' && v >= n) e.push(`${p}: exclusiveMaximum`); },
  required: (r, s, v, p, e) => { if (typeOf(v) === 'object') for (const k of r) if (!(k in v)) e.push(`${p}.${k}: required`); },
  minProperties: (n, s, v, p, e) => { if (typeOf(v) === 'object' && Object.keys(v).length < n) e.push(`${p}: minProperties`); },
  properties: (props, s, v, p, e) => { if (typeOf(v) === 'object') for (const k of Object.keys(props)) if (k in v) check(props[k], v[k], `${p}.${k}`, e); },
  additionalProperties: (ap, s, v, p, e) => {
    if (typeOf(v) !== 'object') return;
    for (const k of Object.keys(v)) if (!(s.properties && k in s.properties)) { if (ap === false) e.push(`${p}.${k}: additionalProperties`); else check(ap, v[k], `${p}.${k}`, e); }
  },
  items: (it, s, v, p, e) => { if (Array.isArray(v)) v.forEach((x, i) => check(it, x, `${p}[${i}]`, e)); },
  prefixItems: (list, s, v, p, e) => { if (Array.isArray(v)) list.forEach((x, i) => { if (i < v.length) check(x, v[i], `${p}[${i}]`, e); }); },
  minItems: (n, s, v, p, e) => { if (Array.isArray(v) && v.length < n) e.push(`${p}: minItems`); },
  maxItems: (n, s, v, p, e) => { if (Array.isArray(v) && v.length > n) e.push(`${p}: maxItems`); },
  uniqueItems: (u, s, v, p, e) => { if (u && Array.isArray(v) && new Set(v.map((x) => JSON.stringify(x))).size !== v.length) e.push(`${p}: uniqueItems`); },
  allOf: (list, s, v, p, e) => { for (const x of list) check(x, v, p, e); },
  anyOf: (list, s, v, p, e) => { if (!list.some((x) => valid(x, v))) e.push(`${p}: anyOf`); },
  oneOf: (list, s, v, p, e) => { if (list.filter((x) => valid(x, v)).length !== 1) e.push(`${p}: oneOf`); },
  if: () => {},
  then: (t, s, v, p, e) => { if (s.if && valid(s.if, v)) check(t, v, p, e); },
  else: (el, s, v, p, e) => { if (s.if && !valid(s.if, v)) check(el, v, p, e); },
};
function check(s, v, path, errs) {
  if (s === true) return;
  for (const key of Object.keys(s)) {
    if (!ANNOTATIONS.has(key) && !KEYWORDS[key]) throw new Error(`schema keyword '${key}' not supported by the test checker`);
  }
  if (s.$ref !== undefined) {
    const m = /^#\/\$defs\/(.+)$/.exec(s.$ref);
    assert.ok(m && schema.$defs[m[1]], `bad $ref ${s.$ref}`);
    check(schema.$defs[m[1]], v, path, errs);
  }
  for (const key of Object.keys(s)) if (KEYWORDS[key] && key !== '$ref') KEYWORDS[key](s[key], s, v, path, errs);
}
const schemaErrors = (r) => { const e = []; check(schema, r, '$', e); return e; };

const DIR = join(ROOT, 'tests/fixtures/rounds/v4c');
const goldens = readdirSync(DIR).filter((f) => f.endsWith('.json')).map((f) => [f, JSON.parse(readFileSync(join(DIR, f), 'utf8'))]);

test('round-v1 schema: draw has optional apex_m (> 0) and land_deg (10–75), not required', () => {
  const d = schema.$defs.stroke.properties.draw;
  assert.deepEqual(d.required, ['seed', 'carry_m', 'side_m']);
  assert.deepEqual(d.properties.apex_m, { type: 'number', exclusiveMinimum: 0 });
  assert.deepEqual(d.properties.land_deg, { type: 'number', minimum: 10, maximum: 75 });
  assert.equal(d.additionalProperties, false);
});

test('engine-played rounds (incl. shaped draws) pass the JSON schema AND validateRound with replay', () => {
  let shaped = 0;
  for (const [f, r] of goldens) {
    assert.deepEqual(schemaErrors(r), [], f);
    const v = validateRound(r, { replayRound });
    assert.ok(v.ok, `${f}: ${JSON.stringify(v.errors.slice(0, 3))}`);
    shaped += r.strokes.filter((s) => 'land_deg' in s.draw).length;
  }
  assert.ok(shaped > 0, 'at least one golden stroke carries an imported flight shape');
});

test('a bad flight shape fails both the schema and validateRound (shape)', () => {
  const [f, r0] = goldens.find(([, r]) => r.strokes.some((s) => 'land_deg' in s.draw));
  for (const [k, bad] of [['land_deg', 80], ['land_deg', 5], ['apex_m', 0], ['spin', 1]]) {
    const r = structuredClone(r0);
    r.strokes.find((s) => 'land_deg' in s.draw).draw[k] = bad;
    assert.ok(schemaErrors(r).length > 0, `${f} schema ${k}=${bad}`);
    const v = validateRound(r);
    assert.ok(!v.ok && v.errors.some((e) => e.rule === 'shape' && e.path.includes('.draw')), `${f} validateRound ${k}=${bad}`);
  }
});
